def cuit_con_guiones(apps, schema_editor):
    """Los CUIT ya cargados (11 dígitos) pasan al formato XX-XXXXXXXX-X."""
    Cliente = apps.get_model("clientes", "Cliente")
    for cliente in Cliente.objects.exclude(cuit=""):
        digitos = "".join(c for c in cliente.cuit if c.isdigit())
        if len(digitos) == 11:
            cliente.cuit = f"{digitos[:2]}-{digitos[2:10]}-{digitos[10]}"
            cliente.save(update_fields=["cuit"])


